    enonce: "<span dir=\"ltr\" class=\"expr pt\">M</span> حجر منتصب <span dir=\"ltr\" class=\"expr\">(</span>منهير<span dir=\"ltr\" class=\"expr\">)</span> يتعذّر الوصول إليه.<br>النّقط <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> و <span dir=\"ltr\" class=\"expr pt\">A</span> على استقامة واحدة، و كذلك <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">D</span> و <span dir=\"ltr\" class=\"expr pt\">B</span>،<br>و <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span> حيث <span dir=\"ltr\" class=\"expr pt\">CD = 102 m</span> و <span dir=\"ltr\" class=\"expr pt\">AB = 238 m</span> و <span dir=\"ltr\" class=\"expr pt\">CA = 168 m.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 292 148\" width=\"292\" height=\"148\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(21.0 24.7)\"><line x1=\"4.1\" y1=\"96.2\" x2=\"245.9\" y2=\"96.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"4.1\" y1=\"96.2\" x2=\"73.2\" y2=\"4.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"245.9\" y1=\"96.2\" x2=\"73.2\" y2=\"4.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"107.7\" y1=\"96.2\" x2=\"33.7\" y2=\"56.7\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"4.1\" cy=\"96.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"-10.3\" y=\"104.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">M</text><circle cx=\"245.9\" cy=\"96.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"260.7\" y=\"102.8\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"73.2\" cy=\"4.1\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"68.9\" y=\"-6.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"107.7\" cy=\"96.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"115.1\" y=\"113.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"33.7\" cy=\"56.7\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"19.1\" y=\"57.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 102</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 238</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 168</span>  و  <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>"},{"quoi":"1)","math":"أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">CM.</span> نختار النّسبة و الجزء الباقي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 102</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 238</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 168.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"القاعدة","math":"إذا عُلمت النّسبة و عُلم الجزء الباقي، أمكن حساب الطولين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 102</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 238</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 168</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CM = 126</span>  ، لأنّ النّسبة <span class=\"frac\" dir=\"ltr\"><span class=\"num\">102</span><span class=\"den\">238</span></span> و الفرق 168"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CM = 126</span>"},{"quoi":"2)","math":"استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AM.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 102</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 238</span>  و  <span dir=\"ltr\" class=\"expr pt\">CM = 126.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">102</span><span class=\"den\">238</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">126</span><span class=\"den\">AM</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AM = 294</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AM = 294</span>"}],
